import csv

def read_employees_above_salary(threshold=50000):
    """
    Reads a CSV file named 'employees.csv' and prints the names of employees
    whose salary exceeds the specified threshold. Handles file not found errors,
    missing headers, and incorrect data types.

    :param threshold: Salary threshold to filter employees (default is 50000)
    """
    try:
        with open('employees.csv', mode='r') as file:
            reader = csv.DictReader(file)

            expected_headers = {'id', 'name', 'position', 'salary'}
            if not expected_headers.issubset(reader.fieldnames):
                raise ValueError("CSV file does not contain the required headers.")

            for row in reader:
                try:
                    salary = float(row['salary'])
                    if salary > threshold:
                        print(row['name'])
                except ValueError as e:
                    print(f"Error reading data from row {row}: {e}")

    except FileNotFoundError:
        print("Error: The file 'employees.csv' was not found.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

# Call the function
read_employees_above_salary()

def restock_items(inventory, restock_info):
    """
    Updates the inventory dictionary with the restock quantities specified in restock_info.

    Parameters:
    inventory (dict): A dictionary with item names as keys and their current stock levels as values.
    restock_info (dict): A dictionary with item names as keys and the quantities to be restocked as values.

    Returns:
    dict: The updated inventory dictionary after restocking.
    """
    for item, quantity in restock_info.items():
        if item in inventory:
            inventory[item] += quantity
        else:
            inventory[item] = quantity
    return inventory

# Example usage:
inventory = {"apple": 30, "banana": 20, "orange": 15}
restock_info = {"apple": 20, "banana": 10}
print(restock_items(inventory, restock_info))

def flatten_list_of_dicts(list_of_dicts):
    """
    Flattens a list of dictionaries into a single dictionary where each key maps to a list of values
    from all dictionaries that share the same key.

    :param list_of_dicts: List of dictionaries to be flattened.
    :return: A dictionary with keys from all input dictionaries and values as lists of corresponding values.
    """
    result = {}
    for dictionary in list_of_dicts:
        for key, value in dictionary.items():
            if key in result:
                result[key].append(value)
            else:
                result[key] = [value]
    return result

def countPrimes(n):
    """
    Returns the count of prime numbers less than n using the Sieve of Eratosthenes algorithm.

    :param n: An integer representing the upper limit (exclusive) for counting prime numbers.
    :return: An integer count of prime numbers less than n.
    """
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for start in range(2, int(n ** 0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n, start):
                sieve[multiple] = False

    return sum(sieve)
